#include "DHT.h"

#define DHTPIN 12
#define DHTTYPE DHT11

DHT dht(DHTPIN, DHTTYPE);

int licznik = 0;
int liczba = 0;

int minimum, maksimum;
int jasnosc, wilgotnosc, temperatura;

char tryb = 'L';

// Funkcja obsługi wyświetlacza
void Znak(int iNumer) {
  igitalWrite(8, ((iNumer == 0) || (iNumer == 1) || (iNumer == 7)) ? HIGH : LOW);

  switch (iNumer) {
    case 0: PORTD = 0b00000000; break;
    case 1: PORTD = 0b11100100; break;
    case 2: PORTD = 0b10010010; break;
    case 3: PORTD = 0b11000010; break;
    case 4: PORTD = 0b01100100; break;
    case 5: PORTD = 0b01001001; break;
    case 6: PORTD = 0b00001001; break;
    case 7: PORTD = 0b11100000; break;
    case 8: PORTD = 0b00000000; break;
    case 9: PORTD = 0b01000000; break;
    default: PORTD = 0b11011000; break;
  }
}

void setup() {
  dht.begin();

  for (int i = 2; i < 9; i++) {
    pinMode(i, OUTPUT);
  }

  pinMode(9, INPUT);
  pinMode(10, OUTPUT);
  pinMode(11, OUTPUT);

  delay(1000);

  minimum = analogRead(A0);
  maksimum = minimum;
}

void loop() {

  digitalWrite(11, LOW);

  delay(2);

  if (licznik++ > 100) {

    jasnosc = analogRead(A0);

    if (minimum > jasnosc)
      minimum = jasnosc;

    if (maksimum < jasnosc)
      maksimum = jasnosc;

    if (minimum != maksimum) {
      jasnosc = 99 * (jasnosc - minimum) /
                (maksimum - minimum);
    }

    wilgotnosc = (int)dht.readHumidity();
    temperatura = (int)dht.readTemperature();

    if (isnan(wilgotnosc))
      wilgotnosc = 0;

    if (isnan(temperatura))
      temperatura = 0;

    switch (tryb) {

      case 'L':
        liczba = jasnosc;
        break;

      case 'H':
        liczba = wilgotnosc;
        break;

      case 'T':
        liczba = temperatura;
        break;
    }

    licznik = 0;

    Znak(liczba);
  }

  // Obsługa przycisku
  if (digitalRead(9) > 0) {

    digitalWrite(10, LOW);
    digitalWrite(11, HIGH);

    if (tryb == 'L') {

      tryb = 'H';
      digitalWrite(8, LOW);
      PORTD = 0b00100100;

    }
    else if (tryb == 'H') {

      tryb = 'T';
      digitalWrite(8, LOW);
      PORTD = 0b00100100;

    }
    else if (tryb == 'T') {

      tryb = 'L';
      digitalWrite(8, LOW);
      PORTD = 0b00100100;
    }

    while (digitalRead(9) > 0) {
      delay(10);
    }
  }
}
